style.css:
@-moz-document domain("pinterest.com") {
/* Background principal */
    body {
        background: #000000 url(https://i.pinimg.com/736x/86/60/d2/8660d2d2d36388ef062d92fc61fe63f8.jpg) center center/cover no-repeat !important;
        color: #ff007f !important;
    }

    /* Header e nav */
    header, nav, [data-test-id="header"], [data-test-id="search-bar"] {
        background-color: rgba(0, 51, 255, 0.1) !important;
        backdrop-filter: blur(10px) !important;
        border-bottom: 2px solid #ff007f !important;
    }

    /* Textos */
    h1, h2, h3, h4, h5, h6, span, p, a {
        color: #ff007f !important;
        font-family: 'Courier New', Courier, monospace !important;
    }

    /* Links ao passar o mouse */
    a:hover {
        color: #0033ff !important;
        text-shadow: 0 0 5px #0033ff;
    }

    /* Cards/Pins */
    [data-test-id="pin"] {
        background-color: rgba(0, 51, 255, 0.07) !important;
        border-radius: 12px !important;
        border: 1px solid #ff007f !important;
        box-shadow: 0 0 15px #ff007f80 !important;
    }

    /* Botões */
    button {
        background-color: #0033ff !important;
        color: #fff !important;
        border: 2px solid #ff007f !important;
        border-radius: 10px !important;
        font-weight: bold !important;
        transition: all 0.3s ease-in-out;
    }

    button:hover {
        background-color: #ff007f !important;
        color: #fff !important;
        border-color: #0033ff !important;
        box-shadow: 0 0 10px #ff007f;
    }

    /* Scrollbar com rosa e azul shock */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #ff007f;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #0033ff;
    }

    /* Input fields */
    input, textarea {
        background-color: rgba(255, 255, 255, 0.05) !important;
        color: #ff007f !important;
        border: 1px solid #0033ff !important;
    }
}
